frappe.web_form.after_load = () => {
    if (window.location.pathname.endsWith("/new") && frappe.session.user) {
        let current_path = window.location.href;
        window.location.href = current_path.replace("/new", "/" + frappe.session.user);
    }
}

$(document).ready(function () {

    // =========================================================================
    //  CONFIG
    // =========================================================================

    var DRAFT_KEY_PREFIX = 'fle_draft_v4_';  // per-user key prefix

    // =========================================================================
    //  USER IDENTITY
    // =========================================================================

    function getUserEmail() {
        var params = new URLSearchParams(window.location.search);
        var urlEmail = params.get('email_address') || params.get('email') || '';
        if (urlEmail && urlEmail.indexOf('@') !== -1) return urlEmail.toLowerCase().trim();

        var emailWrapper = document.querySelector('[data-fieldname="email_address"]');
        if (emailWrapper) {
            var emailInp = emailWrapper.querySelector('input.input-with-feedback');
            if (emailInp && emailInp.value && emailInp.value.indexOf('@') !== -1) {
                return emailInp.value.toLowerCase().trim();
            }
        }

        if (window.frappe && frappe.session && frappe.session.user &&
            frappe.session.user !== 'Guest') {
            return frappe.session.user.toLowerCase().trim();
        }

        return '';
    }

    function getDraftKey() {
        var email = getUserEmail();
        if (!email) return null;
        return DRAFT_KEY_PREFIX + email.replace(/[^a-z0-9@._-]/g, '_');
    }

    var TYPED_FIELDS = {
        'candidate_gender'                    : 'select',
        'candidate_state'                     : 'select',
        'where_did_you_hear'                  : 'select',
        'last_class_attended'                 : 'select',
        'latest_board_attended'               : 'select',
        'year_of_passing'                     : 'select',
        'relationship_with_the_candidate'     : 'select',
        'candidate_nationality'               : 'link',
        'i_hereby_consent_to_this_declaration': 'check',
        // Attach fields — saved as filename strings, restored as visual indicators
        'upload_government_approved_id_card'  : 'attach',
        'upload_candidate_s_photo'            : 'attach'
    };

    var SKIP_FIELDS = { '__newname': true, 'amended_from': true };

    // Attach field fieldnames — also checked by partial match for robustness
    var ATTACH_FIELD_KEYWORDS = ['upload', 'photo', 'id_card', 'document', 'attachment'];

    // Required fields — ALL must be non-empty for "Proceed to Pay" to show
    var REQUIRED_FOR_PAY = [
        'email_address', 'candidate_name', 'candidate_dob',
        'candidate_gender', 'where_did_you_hear',
        'last_class_attended', 'latest_board_attended', 'year_of_passing'
    ];

    // =========================================================================
    //  STORAGE
    // =========================================================================

    var Store = {
        save: function (data) {
            var key = getDraftKey();
            if (!key) { console.warn('[Draft] No user key — cannot save.'); return false; }
            try { localStorage.setItem(key, JSON.stringify(data)); return true; }
            catch (e) { console.error('[Draft] save error:', e); return false; }
        },
        load: function () {
            var key = getDraftKey();
            if (!key) return null;
            try { var r = localStorage.getItem(key); return r ? JSON.parse(r) : null; }
            catch (e) { return null; }
        }
    };

    // =========================================================================
    //  FIELD DISCOVERY
    // =========================================================================

    function discoverFields() {
        var result = [], seen = {};
        document.querySelectorAll('[data-fieldname]').forEach(function (wrapper) {
            var fn = wrapper.getAttribute('data-fieldname');
            if (!fn || seen[fn] || SKIP_FIELDS[fn]) return;

            var explicitType = TYPED_FIELDS[fn];

            // Auto-detect attach fields by keyword if not explicitly typed
            if (!explicitType) {
                var fnLower = fn.toLowerCase();
                for (var k = 0; k < ATTACH_FIELD_KEYWORDS.length; k++) {
                    if (fnLower.indexOf(ATTACH_FIELD_KEYWORDS[k]) !== -1) {
                        // Confirm it has an attach button or hidden file input
                        var hasAttach = wrapper.querySelector(
                            '.attach-btn, .attached-file-wrapper, input[type="hidden"], ' +
                            '.btn.attach-btn, [data-action="attach"]'
                        );
                        if (hasAttach) { explicitType = 'attach'; break; }
                    }
                }
            }

            // For attach fields — accepted even without standard inputs
            if (explicitType === 'attach') {
                seen[fn] = true;
                result.push({ fieldname: fn, type: 'attach' });
                return;
            }

            var chk = wrapper.querySelector('input[type="checkbox"]');
            if (!explicitType && chk) explicitType = 'check';

            var hasInput = wrapper.querySelector(
                'input.input-with-feedback, select, textarea, input[type="checkbox"]'
            );
            if (!hasInput) return;

            seen[fn] = true;
            result.push({ fieldname: fn, type: explicitType || 'text' });
        });
        return result;
    }

    // =========================================================================
    //  READ
    // =========================================================================

    function readField(cfg) {
        var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
        if (!wrapper) return '';

        if (cfg.type === 'check') {
            var chk = wrapper.querySelector('input[type="checkbox"]');
            return chk ? (chk.checked ? '1' : '0') : '';
        }

        // ── Attach field — read filename from hidden input or attached file link ──
        if (cfg.type === 'attach') {
            return readAttach(wrapper);
        }

        if (cfg.type === 'select') {
            // 1. Hidden <select> — most reliable (Frappe's internal state)
            var sel = wrapper.querySelector('select');
            if (sel && sel.value && sel.value.trim()) return sel.value.trim();
            // 2. Display input
            var inp = wrapper.querySelector('input.input-with-feedback');
            if (inp && inp.value && inp.value.trim()) return inp.value.trim();
            // 3. like-disabled-input (read-only display used by some Frappe versions)
            var ldi = wrapper.querySelector('.like-disabled-input');
            if (ldi && ldi.textContent && ldi.textContent.trim()) return ldi.textContent.trim();
            return '';
        }
        if (cfg.type === 'link') {
            var inp2 = wrapper.querySelector('input.input-with-feedback');
            if (inp2 && inp2.value && inp2.value.trim()) return inp2.value.trim();
            return '';
        }
        var inp3 = wrapper.querySelector('input.input-with-feedback');
        if (inp3 && inp3.value && inp3.value.trim()) return inp3.value.trim();
        var ta = wrapper.querySelector('textarea');
        if (ta && ta.value && ta.value.trim()) return ta.value.trim();
        return '';
    }

    // ── Read attach field — returns filename or URL ───────────────────────────
    // Frappe stores uploaded file info in:
    //   1. input[type="hidden"] inside the field wrapper (most reliable)
    //   2. .attached-file-link anchor text or href
    //   3. .attached-file span text
    function readAttach(wrapper) {
        // Hidden input (Frappe sets this after upload)
        var hidden = wrapper.querySelector('input[type="hidden"]');
        if (hidden && hidden.value && hidden.value.trim()) return hidden.value.trim();

        // Attached file link — href contains the file path
        var link = wrapper.querySelector('a.attached-file-link, .attached-file-wrapper a');
        if (link) {
            var href = link.getAttribute('href') || '';
            if (href && href.trim() && href !== '#') return href.trim();
            // Fall back to link text (filename)
            var txt = (link.textContent || link.innerText || '').trim();
            if (txt) return txt;
        }

        // .attached-file span
        var span = wrapper.querySelector('.attached-file, .file-name');
        if (span) {
            var stxt = (span.textContent || span.innerText || '').trim();
            if (stxt) return stxt;
        }

        // data-file-name attribute on wrapper or children
        var dataEl = wrapper.querySelector('[data-file-name]');
        if (dataEl) {
            var dfn = dataEl.getAttribute('data-file-name') || '';
            if (dfn.trim()) return dfn.trim();
        }

        return '';
    }

    // =========================================================================
    //  WRITE
    // =========================================================================

    function writeField(cfg, val) {
        if (val === '' || val === null || val === undefined) return false;
        var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
        if (!wrapper) return false;
        if (cfg.type === 'check')  return writeCheck(wrapper, val);
        if (cfg.type === 'select') return writeSelect(wrapper, val);
        if (cfg.type === 'link')   return writeLink(wrapper, val);
        if (cfg.type === 'attach') return writeAttach(wrapper, val, cfg.fieldname);
        return writeText(wrapper, val);
    }

    function writeCheck(wrapper, val) {
        var chk = wrapper.querySelector('input[type="checkbox"]');
        if (!chk) return false;
        var shouldCheck = (val === '1' || val === true || val === 'true');
        if (chk.checked !== shouldCheck) { chk.checked = shouldCheck; fire(chk, ['change']); }
        return true;
    }

    function writeSelect(wrapper, val) {
        var sel = wrapper.querySelector('select');
        var inp = wrapper.querySelector('input.input-with-feedback');
        var matched = false;
        if (sel) {
            for (var i = 0; i < sel.options.length; i++) {
                var o = sel.options[i];
                if (o.value.trim().toLowerCase() === val.toLowerCase() ||
                    o.text.trim().toLowerCase()  === val.toLowerCase()) {
                    sel.selectedIndex = i; matched = true; break;
                }
            }
            if (matched) fire(sel, ['change']);
        }
        if (inp) { nativeSet(inp, val); fire(inp, ['input', 'change']); inp.blur(); killDropdowns(wrapper); }
        return matched || !!inp;
    }

    function writeLink(wrapper, val) {
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (!inp) return false;
        nativeSet(inp, val);
        fire(inp, ['input', 'change']);
        inp.blur();
        killDropdowns(wrapper);
        setTimeout(function () { killDropdowns(wrapper); inp.blur(); }, 0);
        setTimeout(function () { killDropdowns(wrapper); }, 50);
        setTimeout(function () { killDropdowns(wrapper); }, 150);
        return true;
    }

    function writeText(wrapper, val) {
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (inp) { inp.value = val; fire(inp, ['input', 'change']); return true; }
        var ta = wrapper.querySelector('textarea');
        if (ta)  { ta.value  = val; fire(ta,  ['input', 'change']); return true; }
        return false;
    }

    // ── Restore attach field — cannot re-upload (browser security) ────────────
    // Strategy:
    //   1. Restore the hidden input value so Frappe knows the file is attached
    //   2. Show a visual "previously attached" indicator with the filename
    //   3. Show a warning that the file must be re-uploaded on form submission
    function writeAttach(wrapper, val, fieldname) {
        if (!val || !val.trim()) return false;

        // Extract just the filename from a full path like /files/myfile.pdf
        var filename = val.split('/').pop() || val;

        // 1. Set hidden input so Frappe's form state knows about the file
        var hidden = wrapper.querySelector('input[type="hidden"]');
        if (hidden) {
            hidden.value = val;
            fire(hidden, ['input', 'change']);
        }

        // 2. Remove any existing restore indicator first
        var existingIndicator = wrapper.querySelector('.fle-attach-restored');
        if (existingIndicator) existingIndicator.parentNode.removeChild(existingIndicator);

        // 3. Check if file is already visually shown (already attached this session)
        var alreadyShown = wrapper.querySelector('a.attached-file-link, .attached-file-wrapper a');
        if (alreadyShown) return true; // Already displayed — no need for indicator

        // 4. Show a "previously attached" indicator inside the field wrapper
        var indicator = document.createElement('div');
        indicator.className = 'fle-attach-restored';
        indicator.style.cssText = [
            'display:flex', 'align-items:center', 'gap:8px',
            'background:#f0fdf4', 'border:1px solid #86efac',
            'border-left:4px solid #16a34a', 'border-radius:4px',
            'padding:8px 12px', 'margin-top:6px', 'font-size:12px',
            'font-family:Merriweather,Georgia,serif', 'color:#15803d',
            'font-weight:500', 'flex-wrap:wrap'
        ].join(';');
        indicator.innerHTML =
            '<span style="font-size:15px;">📎</span>' +
            '<span style="flex:1;word-break:break-all;">' +
                '<strong>Previously attached:</strong> ' + filename +
            '</span>' +
            '<span style="font-size:10px;color:#6b7280;display:block;width:100%;margin-top:2px;">' +
                '⚠ Please re-upload this file before submitting.' +
            '</span>';

        // Insert after the attach button row
        var attachBtn = wrapper.querySelector('.attach-btn, [data-action="attach"], .btn');
        if (attachBtn && attachBtn.parentNode) {
            attachBtn.parentNode.insertBefore(indicator, attachBtn.nextSibling);
        } else {
            wrapper.appendChild(indicator);
        }

        return true;
    }

    function nativeSet(inp, val) {
        var desc = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value');
        if (desc && desc.set) desc.set.call(inp, val);
        else inp.value = val;
    }

    function fire(el, types) {
        types.forEach(function (t) {
            el.dispatchEvent(new Event(t, { bubbles: true }));
        });
    }

    function killDropdowns(wrapper) {
        var root = wrapper || document;
        root.querySelectorAll(
            '.dropdown-menu, .awesomplete > ul, ul.awesomplete, .link-field-popup'
        ).forEach(function (dd) {
            dd.style.display    = 'none';
            dd.style.visibility = 'hidden';
            dd.setAttribute('aria-hidden', 'true');
        });
        var aw = root.querySelector && root.querySelector('.awesomplete');
        if (aw) aw.classList.remove('open');
    }

    // =========================================================================
    //  VERIFY
    // =========================================================================

    function verifyField(cfg, expected) {
        // Checkboxes and attach fields don't need DOM verification
        if (cfg.type === 'check' || cfg.type === 'attach') return true;
        var actual = readField(cfg);
        if (!actual) return false;
        return actual.toLowerCase() === expected.toLowerCase();
    }

    // =========================================================================
    //  SAVE DRAFT
    // =========================================================================

    function saveDraft(silent) {
        var fields = discoverFields();
        var userEmail = getUserEmail();
        var draft = {
            __saved_at  : new Date().toLocaleString(),
            __user_email: userEmail,
            __fields    : []
        };

        fields.forEach(function (cfg) {
            var v = readField(cfg);
            draft[cfg.fieldname] = v;
            draft.__fields.push({ fieldname: cfg.fieldname, type: cfg.type });
            if (v) console.log('[Draft] Save:', cfg.fieldname, '(' + cfg.type + ') =', JSON.stringify(v));
        });

        fields.forEach(function (cfg) {
            if (cfg.type === 'check' && draft[cfg.fieldname] === '') draft[cfg.fieldname] = '0';
        });

        // For attach fields — also check frappe_web_form data if available
        // Frappe stores uploaded file refs in frappe.web_form.doc after upload
        try {
            if (window.frappe && frappe.web_form && frappe.web_form.doc) {
                var doc = frappe.web_form.doc;
                fields.forEach(function (cfg) {
                    if (cfg.type === 'attach') {
                        var docVal = doc[cfg.fieldname];
                        if (docVal && docVal.trim && docVal.trim()) {
                            draft[cfg.fieldname] = docVal.trim();
                            console.log('[Draft] Attach from frappe.web_form.doc:', cfg.fieldname, '->', docVal);
                        }
                    }
                });
            }
        } catch(e) { /* frappe.web_form may not exist */ }

        var ok = Store.save(draft);
        if (!silent) {
            showToast(ok
                ? '💾 Draft saved at ' + draft.__saved_at
                : '❌ Could not save — storage unavailable',
                ok ? '#16a34a' : '#dc2626'
            );
        }
        console.log('[Draft] Saved ' + fields.length + ' fields (ok=' + ok + ')');
    }

    // =========================================================================
    //  AUTO-SAVE
    // =========================================================================

    var _autoTimer = null;
    function scheduleAutoSave() {
        clearTimeout(_autoTimer);
        _autoTimer = setTimeout(function () { saveDraft(true); }, 1500);
    }

    // =========================================================================
    //  RESTORE DRAFT
    // =========================================================================

    function restoreDraft() {
        var draft = Store.load();
        if (!draft) return;

        var currentEmail = getUserEmail();
        if (currentEmail && draft.__user_email &&
            draft.__user_email.toLowerCase() !== currentEmail.toLowerCase()) {
            console.warn('[Draft] Draft belongs to', draft.__user_email,
                         '— current user is', currentEmail, '— skipping restore.');
            return;
        }

        var savedFields = (draft.__fields || []).slice();
        var seen = {};
        savedFields.forEach(function (f) { seen[f.fieldname] = true; });
        Object.keys(TYPED_FIELDS).forEach(function (fn) {
            if (!seen[fn] && draft[fn] !== undefined) {
                savedFields.push({ fieldname: fn, type: TYPED_FIELDS[fn] });
            }
        });

        var pending = savedFields.filter(function (cfg) {
            var v = draft[cfg.fieldname];
            if (cfg.type === 'check') return v === '1' || v === '0';
            return !!v;
        });

        if (!pending.length) return;

        console.log('[Draft] Restore pending:', pending.map(function (f) { return f.fieldname; }));

        var attempts = 0, MAX = 80, toastShown = false;

        function attempt() {
            attempts++;
            var still = [];

            pending.forEach(function (cfg) {
                var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
                if (!wrapper) { still.push(cfg); return; }

                if (cfg.type === 'select') {
                    var sel = wrapper.querySelector('select');
                    var inp = wrapper.querySelector('input.input-with-feedback');
                    if (!((sel && sel.options.length > 1) || inp)) { still.push(cfg); return; }
                }

                writeField(cfg, draft[cfg.fieldname]);

                if (!verifyField(cfg, draft[cfg.fieldname])) {
                    still.push(cfg);
                } else {
                    console.log('[Draft] ✅ Restored:', cfg.fieldname, '->', draft[cfg.fieldname]);
                }
            });

            pending = still;

            if (pending.length === 0) {
                onDone(draft, toastShown); toastShown = true;
            } else if (attempts < MAX) {
                setTimeout(attempt, 100);
            } else {
                console.warn('[Draft] Timed out:', pending.map(function (f) { return f.fieldname; }));
                if (!toastShown) { onDone(draft, false); toastShown = true; }
            }
        }

        attempt();
    }

    function onDone(draft, alreadyShown) {
        setTimeout(updatePayBtn, 100);
        if (!alreadyShown && draft.__saved_at) {
            showToast('📋 Draft restored from ' + draft.__saved_at, '#2563eb');
        }
    }

    // =========================================================================
    //  PROCEED TO PAY — MASTER FIX
    //  ─────────────────────────────────────────────────────────────────────────
    //  Root cause of the bug: Frappe's submit button (.btn-primary / submit-btn)
    //  is ALWAYS rendered visible. The old code tried to toggle a CSS class
    //  'show-pay-btn' which was never actually hiding the button.
    //
    //  Fix strategy:
    //    1. On boot, HIDE the submit button immediately via inline style.
    //    2. updatePayBtn() checks ALL required fields every time it is called.
    //    3. If ALL required fields have a non-empty value → show the button.
    //    4. If ANY required field is empty → hide the button.
    //    5. Called on every input/change/blur event AND on a 300ms poll.
    // =========================================================================

    // Selectors that Frappe uses for the "Proceed to Pay" / submit button
    var PAY_BTN_SELECTOR = [
        'button.submit-btn',
        'button.btn-primary.submit-btn',
        '.web-form-footer button.btn-primary',
        '.page-actions button.btn-primary',
        '.form-footer button.btn-primary'
    ].join(', ');

    function getPayBtn() {
        return document.querySelector(PAY_BTN_SELECTOR);
    }

    function allFilled() {
        return REQUIRED_FOR_PAY.every(function (fn) {
            var val = readField({ fieldname: fn, type: TYPED_FIELDS[fn] || 'text' });
            var filled = !!(val && val.trim && val.trim() !== '');
            if (!filled) console.log('[Pay] Missing required field:', fn);
            return filled;
        });
    }

    function updatePayBtn() {
        var btn = getPayBtn();
        if (!btn) return;

        if (allFilled()) {
            // All required fields filled — show the button
            btn.style.removeProperty('display');
            btn.style.setProperty('visibility', 'visible', 'important');
            btn.style.setProperty('opacity', '1', 'important');
            btn.style.setProperty('pointer-events', 'auto', 'important');
        } else {
            // Some required field is empty — hide completely
            btn.style.setProperty('display', 'none', 'important');
            btn.style.setProperty('visibility', 'hidden', 'important');
            btn.style.setProperty('opacity', '0', 'important');
            btn.style.setProperty('pointer-events', 'none', 'important');
        }
    }

    // Hide the pay button the moment it appears in the DOM
    function hidePayBtnImmediately() {
        var btn = getPayBtn();
        if (btn && !btn.__fle_managed) {
            btn.__fle_managed = true;
            btn.style.setProperty('display', 'none', 'important');
            console.log('[Pay] Submit button found and hidden until required fields filled.');
        }
    }

    // MutationObserver watches for Frappe injecting the submit button late
    var _payObserver = new MutationObserver(function () {
        hidePayBtnImmediately();
        updatePayBtn();
    });
    _payObserver.observe(document.body || document.documentElement, {
        childList: true,
        subtree: true
    });

    // =========================================================================
    //  TOAST
    // =========================================================================

    function showToast(msg, bg) {
        $('#fle-draft-toast').remove();
        $('<div id="fle-draft-toast"></div>').text(msg).css({
            position: 'fixed', bottom: '28px', right: '28px',
            background: bg || '#16a34a', color: '#fff',
            padding: '11px 20px', borderRadius: '7px',
            fontSize: '13px', fontWeight: '600',
            fontFamily: "'Merriweather', Georgia, serif",
            boxShadow: '0 4px 16px rgba(0,0,0,0.18)',
            zIndex: 999999, opacity: 0, maxWidth: '360px', lineHeight: '1.5'
        }).appendTo('body').animate({ opacity: 1 }, 250);
        setTimeout(function () {
            $('#fle-draft-toast').animate({ opacity: 0 }, 350, function () { $(this).remove(); });
        }, 3500);
    }

    // =========================================================================
    //  DOB VALIDATION
    // =========================================================================

    function isFutureOrToday(val) {
        if (!val) return false;
        var p = val.split('-');
        if (p.length !== 3) return false;
        var d = p[0].length === 4
            ? new Date(+p[0], +p[1]-1, +p[2])
            : new Date(+p[2], +p[0]-1, +p[1]);
        if (!d || isNaN(d.getTime())) return false;
        var t = new Date(); t.setHours(0, 0, 0, 0);
        return d >= t;
    }

    var dobAlertShown = false;

    function showDOBError() {
        if (dobAlertShown) return;
        dobAlertShown = true;
        $('#dob-error-msg').remove();
        $('[data-fieldname="candidate_dob"]').first().after(
            '<div id="dob-error-msg" style="background:#fff2f2;border:1px solid #e74c3c;' +
            'border-left:4px solid #e74c3c;color:#c0392b;padding:10px 14px;border-radius:4px;' +
            'margin-top:6px;font-size:13px;font-weight:500;font-family:Merriweather,Georgia,serif;' +
            'display:flex;align-items:center;gap:8px;">' +
            '<span style="font-size:16px;">⚠️</span>' +
            'Date of Birth cannot be today or a future date.</div>'
        );
        setTimeout(function () {
            $('#dob-error-msg').fadeOut(400, function () { $(this).remove(); dobAlertShown = false; });
        }, 4000);
    }

    function clearDOB(inp) {
        inp.value = '';
        $(inp).val('').trigger('change');
        fire(inp, ['input', 'change']);
        setTimeout(updatePayBtn, 100);
    }

    function restrictDOB() {
        var inp = document.querySelector(
            '[data-fieldname="candidate_dob"] input.input-with-feedback'
        );
        if (!inp || inp.__dob) return;
        inp.__dob = true;
        inp.addEventListener('change', function () {
            if (isFutureOrToday(inp.value)) { clearDOB(inp); showDOBError(); }
        });
        inp.addEventListener('blur', function () {
            if (isFutureOrToday(inp.value)) { clearDOB(inp); showDOBError(); }
        });
        inp.addEventListener('keyup', function () {
            if (inp.value.length >= 8 && isFutureOrToday(inp.value)) { clearDOB(inp); showDOBError(); }
        });
    }

    // =========================================================================
    //  ATTACH LISTENERS
    // =========================================================================

    function attach() {
        document.querySelectorAll(
            '[data-fieldname] input, [data-fieldname] select, [data-fieldname] textarea'
        ).forEach(function (el) {
            if (el.__b) return;
            el.__b = true;
            el.addEventListener('input',  function () { updatePayBtn(); scheduleAutoSave(); });
            el.addEventListener('change', function () { updatePayBtn(); scheduleAutoSave(); });
            el.addEventListener('blur',   function () { updatePayBtn(); scheduleAutoSave(); });
        });
    }

    // =========================================================================
    //  INJECT SAVE AS DRAFT BUTTON
    //  Strategy: always inject our own branded button with id="fle-save-draft-btn".
    //  We never rely on Frappe's .btn-default (which is "Discard", not "Save as Draft").
    //  Guard: check for #fle-save-draft-btn in DOM — if present and attached, skip.
    //  Re-injects automatically if Frappe re-renders the footer.
    // =========================================================================

    function injectDraftBtn() {
        // Already in DOM and still attached to document — nothing to do
        var existing = document.getElementById('fle-save-draft-btn');
        if (existing && document.body && document.body.contains(existing)) return;

        // Footer container must exist before we can inject
        var $footer = $('.web-form-footer, .page-actions, .form-footer').first();
        if (!$footer.length) return;

        // Build the branded Save as Draft button
        var $btn = $('<button type="button" id="fle-save-draft-btn" class="btn btn-default"></button>')
            .html(
                '<svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" ' +
                'fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" ' +
                'style="margin-right:6px;vertical-align:middle;">' +
                '<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path>' +
                '<polyline points="17 21 17 13 7 13 7 21"></polyline>' +
                '<polyline points="7 3 7 8 15 8"></polyline>' +
                '</svg>Save As Draft'
            )
            .css({
                'all'             : 'unset',
                'box-sizing'      : 'border-box',
                'display'         : 'inline-flex',
                'align-items'     : 'center',
                'justify-content' : 'center',
                'white-space'     : 'nowrap',
                'font-family'     : "'Merriweather', Georgia, serif",
                'font-size'       : '13px',
                'font-weight'     : '700',
                'letter-spacing'  : '0.5px',
                'padding'         : '10px 22px',
                'border-radius'   : '5px',
                'cursor'          : 'pointer',
                'min-height'      : '38px',
                'line-height'     : '1',
                'background-color': '#ffffff',
                'color'           : '#8B0000',
                'border'          : '2px solid #8B0000',
                'box-shadow'      : 'none',
                'transition'      : 'background-color 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease'
            })
            .on('mouseenter', function () {
                $(this).css({
                    'background-color': '#fff4f4',
                    'transform'       : 'translateY(-1px)',
                    'box-shadow'      : '0 2px 8px rgba(139,0,0,0.15)'
                });
            })
            .on('mouseleave', function () {
                $(this).css({
                    'background-color': '#ffffff',
                    'transform'       : 'translateY(0)',
                    'box-shadow'      : 'none'
                });
            })
            .on('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                saveDraft(false);
            });

        // Insert as the FIRST button so order is:
        // [Save as Draft] [Discard] [Proceed to Pay] [Delete]
        $footer.prepend($btn);
        console.log('[Draft] Save as Draft button injected into footer.');
    }

    // =========================================================================
    //  DEBUG
    // =========================================================================

    window.checkFields = function () {
        console.log('===== LIVE FIELD SCAN =====');
        discoverFields().forEach(function (cfg) {
            var v = readField(cfg);
            console.log((v ? '✅' : '❌'), cfg.fieldname, '(' + cfg.type + ')', '->', JSON.stringify(v));
        });
        console.log('allFilled ->', allFilled());
        console.log('Current user ->', getUserEmail());
        console.log('Draft key    ->', getDraftKey());
        console.log('Stored draft ->', Store.load());
        console.log('Pay button   ->', getPayBtn());
        console.log('===========================');
    };

    // =========================================================================
    //  BOOT
    // =========================================================================

    console.log('[FLE] webform.js loaded');

    // Step 1: Immediately hide pay button before Frappe shows it
    hidePayBtnImmediately();

    // Step 2: Restore any saved draft
    restoreDraft();

    // Step 3: Listen for Frappe upload events — save draft after every file upload
    // Frappe fires these events on the document after a successful attachment
    ['upload-complete', 'frappe-upload-done', 'after-upload', 'after_upload'].forEach(function (evt) {
        document.addEventListener(evt, function () {
            console.log('[Draft] Upload event detected:', evt, '— auto-saving draft');
            setTimeout(function () { saveDraft(true); }, 300);
        });
    });

    // Also intercept Frappe's upload callback via MutationObserver on attach wrappers
    // When a file is attached, Frappe inserts an <a> tag inside the wrapper
    var _attachObserver = new MutationObserver(function (mutations) {
        mutations.forEach(function (m) {
            m.addedNodes.forEach(function (node) {
                if (node.nodeType !== 1) return;
                var cls = (node.className || '').toString();
                // Frappe adds .attached-file-wrapper or .attached-file after upload
                if (cls.indexOf('attach') !== -1 || cls.indexOf('file') !== -1 ||
                    node.tagName === 'A') {
                    console.log('[Draft] Attachment detected in DOM — scheduling save');
                    setTimeout(function () { saveDraft(true); }, 400);
                }
            });
        });
    });

    // Observe all attach field wrappers
    setTimeout(function () {
        document.querySelectorAll(
            '[data-fieldname="upload_government_approved_id_card"], ' +
            '[data-fieldname="upload_candidate_s_photo"]'
        ).forEach(function (wrapper) {
            _attachObserver.observe(wrapper, { childList: true, subtree: true });
        });
    }, 1500);

    // Step 4: Poll every 300ms — handles Frappe's async rendering
    setInterval(function () {
        hidePayBtnImmediately();   // catch late-injected button
        restrictDOB();
        attach();
        updatePayBtn();
        injectDraftBtn();

        var d = document.querySelector('[data-fieldname="candidate_dob"] input.input-with-feedback');
        if (d && d.value && isFutureOrToday(d.value)) { clearDOB(d); showDOBError(); }
    }, 300);

    // Step 5: Final boot check after 2s (Frappe fully rendered by now)
    setTimeout(function () {
        restrictDOB();
        attach();
        updatePayBtn();
        injectDraftBtn();
        console.log('[FLE] Boot complete. Fields:', discoverFields().map(function (f) { return f.fieldname; }));
        console.log('[FLE] All required filled:', allFilled());
        // Log attach field status
        ['upload_government_approved_id_card', 'upload_candidate_s_photo'].forEach(function (fn) {
            var v = readField({ fieldname: fn, type: 'attach' });
            console.log('[FLE] Attach field', fn, '->', v || '(empty)');
        });
    }, 2000);

});

